const TEMPLATE_HTML = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Desenvolvido pela DataForge - Dashboard Executivo</title>\n    <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64' fill='none'%3E%3Cdefs%3E%3ClinearGradient id='df-bg' x1='0%25' y1='0%25' x2='100%25' y2='100%25'%3E%3Cstop offset='0%25' stop-color='%230F172A'/%3E%3Cstop offset='100%25' stop-color='%23020617'/%3E%3C/linearGradient%3E%3ClinearGradient id='forge-grad' x1='0%25' y1='100%25' x2='100%25' y2='0%25'%3E%3Cstop offset='0%25' stop-color='%230052CC'/%3E%3Cstop offset='50%25' stop-color='%2300965E'/%3E%3Cstop offset='100%25' stop-color='%2300F59B'/%3E%3C/linearGradient%3E%3ClinearGradient id='spark-grad' x1='0%25' y1='0%25' x2='100%25' y2='100%25'%3E%3Cstop offset='0%25' stop-color='%2338BDF8'/%3E%3Cstop offset='100%25' stop-color='%2300F59B'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='64' height='64' rx='14' fill='url(%23df-bg)'/%3E%3Crect width='62' height='62' x='1' y='1' rx='13' stroke='url(%23forge-grad)' stroke-width='1.5' stroke-opacity='0.4'/%3E%3Cpath d='M14 42L18 36H46L50 42C50 42 44 48 32 48C20 48 14 42 14 42Z' fill='url(%23forge-grad)'/%3E%3Cpath d='M12 28C12 26 14 24 17 24H47C50 24 52 26 52 28C52 30 50 32 46 32H18C14 32 12 30 12 28Z' fill='%2338BDF8' fill-opacity='0.9'/%3E%3Cpath d='M22 32H42L38 38H26L22 32Z' fill='url(%23forge-grad)' fill-opacity='0.8'/%3E%3Cpath d='M32 12L36 19L32 26L28 19L32 12Z' fill='url(%23spark-grad)'/%3E%3Ccircle cx='21' cy='18' r='2' fill='%2300F59B'/%3E%3Ccircle cx='43' cy='18' r='2' fill='%2338BDF8'/%3E%3Cline x1='32' y1='26' x2='32' y2='32' stroke='%2300F59B' stroke-width='1.5' stroke-linecap='round'/%3E%3C/svg%3E\">\n    <style>\n/* {{ CSS_CONTENT }} */\n    </style>\n    <!-- Google Fonts -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n    <!-- Plotly.js -->\n    <script src=\"https://cdn.plot.ly/plotly-2.27.0.min.js\"><\x2Fscript>\n    <!-- Icons (Phosphor Icons for a clean, corporate look) -->\n    <script src=\"https://unpkg.com/@phosphor-icons/web\"><\x2Fscript>\n</head>\n<body>\n    <div class=\"dashboard-layout\">\n        <!-- Main Content -->\n        <main class=\"main-content\">\n            <!-- Header -->\n            <header class=\"topbar\" style=\"position: relative;\">\n                <div class=\"page-title\">\n                    <div style=\"display: flex; align-items: center; gap: 16px;\">\n                        <div class=\"logo-icon\"><i class=\"ph ph-cpu\"></i></div>\n                        <div>\n                            <h1>/* {{ TITLE_CONTENT }} */</h1>\n                            <p>/* {{ DESC_CONTENT }} */</p>\n                        </div>\n                    </div>\n                </div>\n                \n                <!-- Branding removida a pedido do usu\u00e1rio -->\n                <div style=\"display: flex; align-items: center; justify-content: center; gap: 16px; flex: 1;\">\n                </div>\n\n                <div style=\"display: flex; align-items: center; gap: 16px;\">\n                    <div class=\"filter-section\">\n                        <label for=\"risk-filter\"><i class=\"ph ph-funnel\"></i> Filtro Geral:</label>\n                        <select id=\"risk-filter\" class=\"corporate-select\">\n                            <option value=\"all\">Todos os Riscos</option>\n                            <!-- Populated via JS -->\n                        </select>\n                    </div>\n                    <button id=\"export-btn\" class=\"icon-btn export-anim-btn\" title=\"Exportar Dashboard (PDF ou Imprimir)\" style=\"background:var(--primary-blue); color: white; border:none; height: 40px; padding: 0 16px; display:flex; align-items:center; gap: 8px; border-radius:8px; font-weight: 600; cursor: pointer; transition: all 0.3s ease;\"><i class=\"ph ph-printer\" style=\"font-size: 1.2rem;\"></i> Exportar / PDF</button>\n                    <button id=\"settings-btn\" class=\"icon-btn\" title=\"Configura\u00e7\u00f5es\" style=\"background:var(--card-bg); border:1px solid var(--border-color); width: 40px; height: 40px; display:flex; align-items:center; justify-content:center; border-radius:8px;\"><i class=\"ph ph-gear\" style=\"font-size: 1.2rem;\"></i></button>\n                </div>\n            </header>\n\n            <!-- Dashboard Grid -->\n            <div class=\"dashboard-container\">\n                <!-- KPIs -->\n                <div class=\"kpi-grid\">\n                    <div class=\"kpi-card\" id=\"kpi-card-total\">\n                        <div class=\"kpi-icon blue\"><i class=\"ph ph-warning-circle\"></i></div>\n                        <div class=\"kpi-details\">\n                            <h3>Total de Riscos Mapeados</h3>\n                            <h2 id=\"kpi-total\">-</h2>\n                            <span class=\"trend neutral\" id=\"kpi-most-found\"><i class=\"ph ph-info\"></i> Analisando...</span>\n                        </div>\n                    </div>\n                    <div class=\"kpi-card\" id=\"kpi-card-super\">\n                        <div class=\"kpi-icon red\"><i class=\"ph ph-fire\"></i></div>\n                        <div class=\"kpi-details\">\n                            <h3>Riscos Supercr\u00edticos</h3>\n                            <h2 id=\"kpi-supercriticos\">-</h2>\n                            <span class=\"trend negative\"><i class=\"ph ph-trend-up\"></i> A\u00e7\u00e3o imediata requerida</span>\n                        </div>\n                    </div>\n                    <div class=\"kpi-card\" id=\"kpi-card-criticos\">\n                        <div class=\"kpi-icon orange\"><i class=\"ph ph-warning\"></i></div>\n                        <div class=\"kpi-details\">\n                            <h3>Riscos Cr\u00edticos</h3>\n                            <h2 id=\"kpi-criticos\">-</h2>\n                            <span class=\"trend neutral\">Est\u00e1vel</span>\n                        </div>\n                    </div>\n                    <div class=\"kpi-card\" id=\"kpi-card-medios\">\n                        <div class=\"kpi-icon green\"><i class=\"ph ph-shield-check\"></i></div>\n                        <div class=\"kpi-details\">\n                            <h3>Riscos M\u00e9dios/Baixos</h3>\n                            <h2 id=\"kpi-medios\">-</h2>\n                            <span class=\"trend positive\">Sob controle</span>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Charts Section 1 -->\n                <div class=\"charts-row\">\n                    <div class=\"chart-card main-chart\">\n                        <div class=\"card-header\">\n                            <h3>Top 5 Maiores Riscos (Gasto M\u00e9dio)</h3>\n                            <div class=\"local-filter-container\">\n                                <select class=\"corporate-select local-filter-select\" data-filter-type=\"risk\" data-target=\"chart-cost\"><option value=\"all\">Filtrar Risco (Todos)</option></select>\n                                <button class=\"clear-filter-btn\" data-target=\"chart-cost\" style=\"display:none;\" title=\"Remover Filtro\"><i class=\"ph ph-x\"></i></button>\n                            </div>\n                        </div>\n                        <div class=\"chart-body\" id=\"chart-cost\"></div>\n                    </div>\n                    <div class=\"chart-card\">\n                        <div class=\"card-header\">\n                            <h3>Riscos por \u00c1rea de Neg\u00f3cio</h3>\n                            <div class=\"local-filter-container\">\n                                <select class=\"corporate-select local-filter-select\" data-filter-type=\"risk\" data-target=\"chart-area\"><option value=\"all\">Filtrar Risco (Todos)</option></select>\n                                <button class=\"clear-filter-btn\" data-target=\"chart-area\" style=\"display:none;\" title=\"Remover Filtro\"><i class=\"ph ph-x\"></i></button>\n                            </div>\n                        </div>\n                        <div class=\"chart-body\" id=\"chart-area\"></div>\n                    </div>\n                </div>\n\n                <!-- Charts Section 2 -->\n                <div class=\"charts-row three-cols\">\n                    <div class=\"chart-card\">\n                        <div class=\"card-header\">\n                            <h3>Distribui\u00e7\u00e3o por Categoria</h3>\n                            <div class=\"local-filter-container\">\n                                <select class=\"corporate-select local-filter-select\" data-filter-type=\"risk\" data-target=\"chart-category\"><option value=\"all\">Filtrar Risco (Todos)</option></select>\n                                <button class=\"clear-filter-btn\" data-target=\"chart-category\" style=\"display:none;\" title=\"Remover Filtro\"><i class=\"ph ph-x\"></i></button>\n                            </div>\n                        </div>\n                        <div class=\"chart-body\" id=\"chart-category\"></div>\n                    </div>\n                    <div class=\"chart-card col-span-2\">\n                        <div class=\"card-header\">\n                            <h3>Top 5 Maiores Custos Mensais</h3>\n                            <div class=\"local-filter-container\">\n                                <select class=\"corporate-select local-filter-select\" data-filter-type=\"risk\" data-target=\"top-risks-table\"><option value=\"all\">Filtrar Risco (Todos)</option></select>\n                                <select class=\"corporate-select local-filter-select\" data-filter-type=\"class\" data-target=\"top-risks-table\"><option value=\"all\">Filtrar Classifica\u00e7\u00e3o (Todos)</option></select>\n                                <button class=\"clear-filter-btn\" data-target=\"top-risks-table\" style=\"display:none;\" title=\"Remover Filtro\"><i class=\"ph ph-x\"></i></button>\n                            </div>\n                        </div>\n                        <div class=\"table-responsive\">\n                            <table class=\"corporate-table\" id=\"top-risks-table\">\n                                <thead>\n                                    <tr>\n                                        <th>ID</th>\n                                        <th>Risco</th>\n                                        <th>\u00c1rea</th>\n                                        <th>Classifica\u00e7\u00e3o</th>\n                                        <th>Custo Mensal</th>\n                                        <th>Vulnerabilidades</th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <!-- Populated via JS -->\n                                </tbody>\n                            </table>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Full Table Section -->\n                <div class=\"chart-card\" style=\"margin-top: 24px;\">\n                    <div class=\"card-header\">\n                        <h3>Lista Completa de Riscos Identificados</h3>\n                        <div class=\"local-filter-container\">\n                            <select class=\"corporate-select local-filter-select\" data-filter-type=\"risk\" data-target=\"risks-table\"><option value=\"all\">Filtrar Risco (Todos)</option></select>\n                            <select class=\"corporate-select local-filter-select\" data-filter-type=\"class\" data-target=\"risks-table\"><option value=\"all\">Filtrar Classifica\u00e7\u00e3o (Todos)</option></select>\n                            <button class=\"clear-filter-btn\" data-target=\"risks-table\" style=\"display:none;\" title=\"Remover Filtro\"><i class=\"ph ph-x\"></i></button>\n                        </div>\n                    </div>\n                    <div class=\"table-responsive\">\n                        <table class=\"corporate-table\" id=\"risks-table\">\n                            <thead>\n                                <tr>\n                                    <th>ID</th>\n                                    <th>Risco</th>\n                                    <th>\u00c1rea</th>\n                                    <th>Classifica\u00e7\u00e3o</th>\n                                    <th>Custo Mensal</th>\n                                    <th>Gasto M\u00e9dio</th>\n                                    <th>Vulnerabilidades</th>\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <!-- Populated via JS -->\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Settings Panel (bottom left) -->\n            <div id=\"settings-panel\" class=\"settings-panel hidden\">\n                <div class=\"settings-header\">\n                    <h4><i class=\"ph ph-gear\"></i> Configura\u00e7\u00f5es</h4>\n                    <button id=\"close-settings-btn\" class=\"icon-btn\"><i class=\"ph ph-x\"></i></button>\n                </div>\n                <div class=\"settings-body\">\n                    <div class=\"settings-item\">\n                        <label>Apar\u00eancia</label>\n                        <select id=\"theme-selector\" class=\"corporate-select\" style=\"border: 1px solid var(--border-color); border-radius: 4px; padding: 4px 8px; width: 100%;\">\n                            <option value=\"light\">Modo Claro</option>\n                            <option value=\"dark\">Modo Escuro</option>\n                        </select>\n                    </div>\n                    <div class=\"settings-item\" style=\"margin-top: 12px;\">\n                        <label>Editor Master (Layout)</label>\n                        <select id=\"editor-mode\" class=\"corporate-select\" style=\"border: 1px solid var(--border-color); border-radius: 4px; padding: 4px 8px; width: 100%;\">\n                            <option value=\"off\">Bloqueado</option>\n                            <option value=\"on\">Habilitar Arrastar (Drag & Drop)</option>\n                        </select>\n                    </div>\n                </div>\n            </div>\n\n        </main>\n    </div>\n    <script>\n/* {{ DATA_CONTENT }} */\n    <\x2Fscript>\n    <script>\n/* {{ JS_CONTENT }} */\n    <\x2Fscript>\n</body>\n</html>";
const TEMPLATE_CSS = ":root {\n    /* Atl\u00e2ntica Financeira Palette: Green, White, Blue */\n    --primary-blue: #004A8F; /* Deep corporate blue */\n    --secondary-blue: #0066CC;\n    --light-blue: #E6F0FA;\n    --primary-green: #00965E; /* Trust/Growth green */\n    --secondary-green: #00B371;\n    --light-green: #E6F7F0;\n    --bg-color: #F4F7F6;\n    --card-bg: #FFFFFF;\n    \n    /* Text colors */\n    --text-main: #2D3748;\n    --text-muted: #718096;\n    --text-light: #A0AEC0;\n    \n    /* Status Colors */\n    --status-super-critical: #E53E3E; /* Red */\n    --status-critical: #DD6B20; /* Orange */\n    --status-medium: #D69E2E; /* Yellow/Gold */\n    --status-low: #38A169; /* Green */\n    \n    /* UI elements */\n    --border-color: #E2E8F0;\n    --shadow-sm: 0 1px 3px rgba(0,0,0,0.05);\n    --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.05), 0 2px 4px -1px rgba(0,0,0,0.03);\n    --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.05), 0 4px 6px -2px rgba(0,0,0,0.025);\n    --border-radius: 8px;\n    --transition: all 0.2s ease-in-out;\n}\n\n/* Modo Escuro */\nbody.dark-mode {\n    --bg-color: #0F172A;\n    --card-bg: #1E293B;\n    --text-main: #F1F5F9;\n    --text-muted: #94A3B8;\n    --border-color: #334155;\n}\n\n* {\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n    font-family: 'Inter', -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n}\n\nbody {\n    background-color: var(--bg-color);\n    color: var(--text-main);\n    overflow-x: hidden;\n}\n\n/* Layout */\n.dashboard-layout {\n    display: flex;\n    min-height: 100vh;\n}\n\n/* Sidebar */\n.sidebar {\n    width: 260px;\n    background-color: var(--primary-blue);\n    color: #fff;\n    display: flex;\n    flex-direction: column;\n    box-shadow: var(--shadow-lg);\n    z-index: 10;\n}\n\n.logo-container {\n    padding: 24px;\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    border-bottom: 1px solid rgba(255,255,255,0.1);\n}\n\n.logo-icon {\n    font-size: 32px;\n    color: var(--primary-green);\n    background: #fff;\n    border-radius: 8px;\n    width: 40px;\n    height: 40px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n}\n\n.logo-text h2 {\n    font-size: 1.2rem;\n    font-weight: 700;\n    letter-spacing: 0.5px;\n    margin: 0;\n}\n\n.logo-text p {\n    font-size: 0.75rem;\n    color: #CBD5E0;\n    margin: 0;\n}\n\n.nav-menu {\n    padding: 24px 0;\n    flex: 1;\n}\n\n.nav-item {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 12px 24px;\n    color: #E2E8F0;\n    text-decoration: none;\n    font-weight: 500;\n    transition: var(--transition);\n}\n\n.nav-item i {\n    font-size: 1.25rem;\n}\n\n.nav-item:hover {\n    background-color: rgba(255,255,255,0.05);\n    color: #fff;\n}\n\n.nav-item.active {\n    background-color: var(--secondary-blue);\n    color: #fff;\n    border-left: 4px solid var(--primary-green);\n}\n\n.sidebar-footer {\n    padding: 12px 0;\n    border-top: 1px solid rgba(255,255,255,0.1);\n}\n\n/* Main Content */\n.main-content {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    overflow-y: auto;\n}\n\n/* Topbar */\n.topbar {\n    background-color: var(--card-bg);\n    padding: 20px 32px;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    box-shadow: var(--shadow-sm);\n    z-index: 5;\n}\n\n.page-title h1 {\n    font-size: 1.5rem;\n    font-weight: 600;\n    color: var(--primary-blue);\n    margin-bottom: 4px;\n}\n\n.page-title p {\n    font-size: 0.875rem;\n    color: var(--text-muted);\n}\n\n.user-profile {\n    display: flex;\n    align-items: center;\n    gap: 20px;\n}\n\n.search-box {\n    display: flex;\n    align-items: center;\n    background-color: var(--bg-color);\n    padding: 8px 16px;\n    border-radius: 20px;\n    border: 1px solid var(--border-color);\n}\n\n.search-box i {\n    color: var(--text-muted);\n    margin-right: 8px;\n}\n\n.search-box input {\n    border: none;\n    background: transparent;\n    outline: none;\n    font-size: 0.875rem;\n    width: 200px;\n}\n\n.icon-btn {\n    background: transparent;\n    border: none;\n    font-size: 1.25rem;\n    color: var(--text-muted);\n    cursor: pointer;\n    position: relative;\n    transition: var(--transition);\n}\n\n.icon-btn:hover {\n    color: var(--primary-blue);\n}\n\n.badge {\n    position: absolute;\n    top: -5px;\n    right: -5px;\n    background-color: var(--status-super-critical);\n    color: white;\n    font-size: 0.6rem;\n    font-weight: bold;\n    border-radius: 50%;\n    width: 14px;\n    height: 14px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n}\n\n.avatar img {\n    width: 40px;\n    height: 40px;\n    border-radius: 50%;\n    border: 2px solid var(--primary-green);\n    cursor: pointer;\n}\n\n/* Dashboard Container */\n.dashboard-container {\n    padding: 32px;\n    display: flex;\n    flex-direction: column;\n    gap: 24px;\n}\n\n/* KPI Grid */\n.kpi-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n    gap: 24px;\n}\n\n.kpi-card {\n    background: var(--card-bg);\n    border-radius: 12px;\n    padding: 24px;\n    display: flex;\n    align-items: flex-start;\n    gap: 16px;\n    box-shadow: 0 4px 6px rgba(0,0,0,0.02);\n    border: 1px solid var(--border-color);\n    cursor: pointer;\n    transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n}\n\n.kpi-card:hover {\n    transform: translateY(-4px);\n    box-shadow: 0 10px 20px rgba(0,0,0,0.08);\n    border-color: var(--primary-blue);\n}\n\n.kpi-icon {\n    width: 48px;\n    height: 48px;\n    border-radius: 12px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 1.5rem;\n    white-space: nowrap;\n}\n\n/* Fix text contrast in select options for Dark Mode */\nbody.dark-mode select option {\n    background-color: var(--card-bg);\n    color: var(--text-main);\n}\n\n/* Master Editor Mode */\nbody.editor-mode-active .chart-card {\n    cursor: grab;\n    border: 2px dashed var(--primary-blue);\n    position: relative;\n}\n\nbody.editor-mode-active .chart-card:active {\n    cursor: grabbing;\n}\n\nbody.editor-mode-active .chart-card::before {\n    content: \"Arraste para trocar\";\n    position: absolute;\n    top: 12px;\n    left: 50%;\n    transform: translateX(-50%);\n    background: var(--primary-blue);\n    color: #fff;\n    font-size: 0.75rem;\n    padding: 4px 12px;\n    border-radius: 12px;\n    z-index: 100;\n    pointer-events: none;\n    box-shadow: 0 4px 6px rgba(0,0,0,0.2);\n}\n\n.chart-card.drag-over {\n    opacity: 0.6;\n    border-color: var(--status-critical) !important;\n}\n\n.kpi-icon.blue { background-color: var(--light-blue); color: var(--primary-blue); }\n.kpi-icon.red { background-color: #FED7D7; color: var(--status-super-critical); }\n.kpi-icon.orange { background-color: #FEEBC8; color: var(--status-critical); }\n.kpi-icon.green { background-color: var(--light-green); color: var(--primary-green); }\n\n.kpi-details h3 {\n    font-size: 0.875rem;\n    color: var(--text-muted);\n    font-weight: 500;\n    margin-bottom: 8px;\n}\n\n.kpi-details h2 {\n    font-size: 1.75rem;\n    font-weight: 700;\n    color: var(--text-main);\n    margin-bottom: 8px;\n}\n\n.trend {\n    font-size: 0.75rem;\n    font-weight: 500;\n    display: flex;\n    align-items: center;\n    gap: 4px;\n}\n\n.trend.positive { color: var(--primary-green); }\n.trend.negative { color: var(--status-super-critical); }\n.trend.neutral { color: var(--text-muted); }\n\n/* Charts Area */\n.charts-row {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 24px;\n}\n\n.charts-row.three-cols {\n    grid-template-columns: 1fr 2fr;\n}\n\n.chart-card {\n    background: var(--card-bg);\n    border-radius: 12px;\n    box-shadow: 0 4px 6px rgba(0,0,0,0.02);\n    border: 1px solid var(--border-color);\n    display: flex;\n    flex-direction: column;\n    overflow: hidden;\n}\n\n.col-span-2 {\n    /* grid-column: span 2; */ /* Handled by grid-template-columns on parent */\n}\n\n.card-header {\n    padding: 16px 24px;\n    border-bottom: 1px solid var(--border-color);\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n}\n\n.card-header h3 {\n    font-size: 1rem;\n    font-weight: 600;\n    color: var(--text-main);\n}\n\n.chart-body {\n    padding: 16px;\n    min-height: 450px;\n    flex: 1;\n}\n\n/* Filter styles */\n.filter-section {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    background: var(--bg-color);\n    padding: 8px 16px;\n    border-radius: 8px;\n    border: 1px solid var(--border-color);\n}\n\n.filter-section label {\n    font-weight: 600;\n    color: var(--primary-blue);\n    display: flex;\n    align-items: center;\n    gap: 6px;\n}\n\n.corporate-select {\n    border: none;\n    background: transparent;\n    font-size: 1rem;\n    color: var(--text-main);\n    outline: none;\n    cursor: pointer;\n    font-family: inherit;\n    padding: 4px;\n}\n\n.local-filter-container {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    background: var(--card-bg);\n    padding: 6px 14px;\n    border-radius: 6px;\n    border: 1px solid var(--border-color);\n}\n\n.local-filter-select {\n    font-size: 0.9rem;\n    max-width: 250px;\n    padding-right: 8px;\n    text-overflow: ellipsis;\n}\n\n/* Espa\u00e7amento e separa\u00e7\u00e3o para os filtros duplos nas tabelas */\n.local-filter-select[data-filter-type=\"risk\"] + .local-filter-select[data-filter-type=\"class\"] {\n    margin-left: 12px;\n    padding-left: 16px;\n    border-left: 1px solid var(--border-color);\n}\n\n.clear-filter-btn {\n    background: transparent;\n    border: none;\n    color: var(--status-super-critical);\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    padding: 2px;\n    border-radius: 50%;\n    transition: background 0.2s;\n}\n\n.clear-filter-btn:hover {\n    background: rgba(229, 62, 62, 0.1);\n}\n\n/* Table */\n.table-responsive {\n    overflow-x: auto;\n    padding: 0 16px 16px 16px;\n}\n\n.corporate-table {\n    width: 100%;\n    border-collapse: collapse;\n    margin-top: 16px;\n}\n\n.corporate-table th {\n    text-align: left;\n    padding: 12px 16px;\n    font-size: 0.75rem;\n    font-weight: 600;\n    color: var(--text-muted);\n    text-transform: uppercase;\n    letter-spacing: 0.5px;\n    border-bottom: 2px solid var(--border-color);\n}\n\n.corporate-table td {\n    padding: 16px;\n    font-size: 0.875rem;\n    border-bottom: 1px solid var(--border-color);\n    color: var(--text-main);\n}\n\n.corporate-table tbody tr:hover {\n    background-color: rgba(0, 74, 143, 0.02); /* Slight primary blue hover */\n}\n\n.badge-status {\n    padding: 4px 10px;\n    border-radius: 12px;\n    font-size: 0.75rem;\n    font-weight: 600;\n    display: inline-block;\n}\n\n.badge-supercritico { background-color: #FED7D7; color: #C53030; }\n.badge-critico { background-color: #FEEBC8; color: #C05621; }\n.badge-medio { background-color: #FEFCBF; color: #975A16; }\n.badge-baixo { background-color: #C6F6D5; color: #276749; }\n\n/* Responsive adjustments */\n@media (max-width: 1024px) {\n    .charts-row, .charts-row.three-cols {\n        grid-template-columns: 1fr;\n    }\n}\n\n@media (max-width: 768px) {\n    .dashboard-layout {\n        flex-direction: column;\n    }\n    \n    .sidebar {\n        width: 100%;\n        flex-direction: row;\n        justify-content: space-between;\n        align-items: center;\n        padding: 0 16px;\n    }\n\n    .nav-menu {\n        display: none; /* In a real app, use a hamburger menu */\n    }\n    \n    .sidebar-footer {\n        display: none;\n    }\n\n    .kpi-grid {\n        grid-template-columns: 1fr;\n    }\n}\n/* Settings Panel */\n.settings-panel {\n    position: fixed;\n    bottom: 24px;\n    left: 24px;\n    width: 280px;\n    background: var(--card-bg);\n    border: 1px solid var(--border-color);\n    border-radius: 12px;\n    box-shadow: 0 10px 25px rgba(0,0,0,0.15);\n    z-index: 1000;\n    padding: 16px;\n    transition: transform 0.3s ease, opacity 0.3s ease;\n}\n\n.settings-panel.hidden {\n    transform: translateY(20px);\n    opacity: 0;\n    pointer-events: none;\n}\n\n.settings-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 16px;\n    color: var(--primary-blue);\n}\n\n.settings-header h4 {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n\n.settings-item {\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n}\n\n.settings-item label {\n    font-size: 0.875rem;\n    color: var(--text-muted);\n    font-weight: 600;\n}\n\n/* Print / Export Styles */\n@media print {\n    @page { \n        margin: 1cm; \n        size: A4 landscape; \n    }\n    \n    /* For\u00e7a vari\u00e1veis do Modo Escuro de volta ao Modo Claro para impress\u00e3o */\n    :root, body.dark-mode {\n        --bg-color: #FFFFFF !important;\n        --card-bg: #FFFFFF !important;\n        --text-main: #000000 !important;\n        --text-muted: #4A5568 !important;\n        --border-color: #E2E8F0 !important;\n    }\n    \n    body { \n        background-color: #FFFFFF !important; \n        color: #000000 !important; \n    }\n    \n    /* For\u00e7a textos dentro dos gr\u00e1ficos Plotly (SVG) a ficarem pretos */\n    .js-plotly-plot .plotly text,\n    .plotly-chart text,\n    .chart-body text {\n        fill: #000000 !important;\n    }\n    .topbar .filter-section, \n    .topbar #settings-btn, \n    .topbar #export-btn, \n    .settings-panel, \n    .local-filter-container, \n    .upload-container,\n    .clear-filter-btn { \n        display: none !important; \n    }\n    \n    /* Stack elements vertically so they take 100% width and don't force page downscaling */\n    .charts-row, .three-cols {\n        display: block !important;\n        width: 100% !important;\n    }\n    \n    .chart-card, .kpi-card { \n        box-shadow: none !important; \n        border: 1px solid #ddd !important; \n        background-color: #FFFFFF !important;\n        width: 100% !important;\n        margin-bottom: 24px !important;\n        page-break-inside: avoid !important;\n        break-inside: avoid !important;\n        box-sizing: border-box;\n    }\n    \n    .plotly-chart, .chart-body {\n        max-width: 100% !important;\n        height: auto !important;\n        max-height: 450px !important;\n    }\n    \n    .kpi-grid {\n        display: flex !important;\n        flex-wrap: wrap !important;\n        gap: 12px !important;\n    }\n    \n    .kpi-card {\n        flex: 1 1 45% !important;\n        margin-bottom: 12px !important;\n    }\n    \n    .dashboard-container { \n        display: block !important;\n        width: 100% !important;\n    }\n    \n    .topbar { \n        background-color: transparent !important; \n        box-shadow: none !important; \n        border-bottom: 2px solid #000; \n        padding: 0 !important; \n        margin-bottom: 20px; \n    }\n    \n    .corporate-table th {\n        background-color: #f1f5f9 !important;\n        color: #000 !important;\n        -webkit-print-color-adjust: exact;\n        print-color-adjust: exact;\n    }\n}\n/* Export Button Animation */\n.export-anim-btn:hover {\n    transform: translateY(-2px);\n    box-shadow: 0 4px 12px rgba(0, 74, 143, 0.3);\n}\n.export-anim-btn:active {\n    transform: translateY(0);\n}\n";
const TEMPLATE_JS = "let allRiscos = [];\nlet currentGlobalFilter = 'all';\n\ndocument.addEventListener(\"DOMContentLoaded\", () => {\n    try {\n        if (typeof dashboardData === 'undefined') {\n            throw new Error(\"Dados n\u00e3o encontrados. Certifique-se de que o Python gerou o arquivo dados.js corretamente.\");\n        }\n        \n        allRiscos = dashboardData.riscos;\n        \n        // Filtros globais e locais\n        const globalFilterSelect = document.getElementById('risk-filter');\n        \n        // 1. Popula selects de Gr\u00e1ficos e Tabelas (por Risco)\n        const riskSelects = document.querySelectorAll('.local-filter-select[data-filter-type=\"risk\"]');\n        allRiscos.forEach(r => {\n            const optGlobal = document.createElement('option');\n            optGlobal.value = r.ID;\n            optGlobal.textContent = `${r.ID} - ${r.Risco} (${r.\u00c1rea})`;\n            globalFilterSelect.appendChild(optGlobal);\n\n            riskSelects.forEach(select => {\n                const optLocal = document.createElement('option');\n                optLocal.value = r.ID;\n                optLocal.textContent = `${r.ID} - ${r.Risco}`;\n                select.appendChild(optLocal);\n            });\n        });\n\n        // 2. Popula selects de Tabelas (por Classifica\u00e7\u00e3o)\n        const classSelects = document.querySelectorAll('.local-filter-select[data-filter-type=\"class\"]');\n        const baseClasses = ['Super cr\u00edtico', 'Cr\u00edtico', 'M\u00e9dio', 'Baixo'];\n        const existingClasses = [...new Set(allRiscos.map(r => r['Classifica\u00e7\u00e3o']))];\n        const uniqueClasses = [...new Set([...baseClasses, ...existingClasses])];\n        \n        uniqueClasses.forEach(c => {\n            classSelects.forEach(select => {\n                const opt = document.createElement('option');\n                opt.value = c;\n                opt.textContent = c;\n                select.appendChild(opt);\n            });\n        });\n\n        const allLocalSelects = document.querySelectorAll('.local-filter-select');\n\n        // Evento de mudan\u00e7a global\n        globalFilterSelect.addEventListener('change', (e) => {\n            currentGlobalFilter = e.target.value;\n            updateDashboard();\n        });\n\n        // Evento de mudan\u00e7a locais\n        allLocalSelects.forEach(select => {\n            select.addEventListener('change', (e) => {\n                const target = e.target.getAttribute('data-target');\n                const widgetSelects = document.querySelectorAll(`.local-filter-select[data-target=\"${target}\"]`);\n                const btn = document.querySelector(`.clear-filter-btn[data-target=\"${target}\"]`);\n                \n                let hasActive = false;\n                widgetSelects.forEach(s => {\n                    if (s.value !== 'all') hasActive = true;\n                });\n                \n                btn.style.display = hasActive ? 'flex' : 'none';\n                updateWidget(target);\n            });\n        });\n\n        // Evento de limpar filtro local\n        const clearBtns = document.querySelectorAll('.clear-filter-btn');\n        clearBtns.forEach(btn => {\n            btn.addEventListener('click', (e) => {\n                const btnTarget = e.currentTarget;\n                const target = btnTarget.getAttribute('data-target');\n                \n                const widgetSelects = document.querySelectorAll(`.local-filter-select[data-target=\"${target}\"]`);\n                widgetSelects.forEach(s => s.value = 'all');\n                \n                btnTarget.style.display = 'none';\n                updateWidget(target);\n            });\n        });\n\n        // Renderiza\u00e7\u00e3o inicial com todos os riscos\n        updateDashboard();\n\n        // ---------------------------------------------------------\n        // L\u00f3gica de clique nos KPIs (navegar e filtrar)\n        // ---------------------------------------------------------\n        function applyTableFilterAndScroll(targetWidgetId, filterType, filterValueFallbackArray) {\n            const classSelect = document.querySelector(`.local-filter-select[data-filter-type=\"class\"][data-target=\"${targetWidgetId}\"]`);\n            const riskSelect = document.querySelector(`.local-filter-select[data-filter-type=\"risk\"][data-target=\"${targetWidgetId}\"]`);\n            const clearBtn = document.querySelector(`.clear-filter-btn[data-target=\"${targetWidgetId}\"]`);\n            \n            if (riskSelect) {\n                if (currentGlobalFilter !== 'all') {\n                    riskSelect.value = currentGlobalFilter;\n                } else {\n                    riskSelect.value = 'all';\n                }\n            }\n\n            if (classSelect) {\n                if (filterType === 'all') {\n                    classSelect.value = 'all';\n                } else {\n                    let valueToSet = 'all';\n                    for (const val of filterValueFallbackArray) {\n                        const optionExists = Array.from(classSelect.options).some(opt => opt.value === val);\n                        if (optionExists) {\n                            valueToSet = val;\n                            break;\n                        }\n                    }\n                    classSelect.value = valueToSet;\n                }\n\n                if (clearBtn) {\n                    clearBtn.style.display = (classSelect.value !== 'all' || riskSelect.value !== 'all') ? 'flex' : 'none';\n                }\n            }\n            \n            updateWidget(targetWidgetId);\n            \n            const tableContainer = document.querySelector(`.local-filter-select[data-target=\"${targetWidgetId}\"]`).closest('.chart-card');\n            if (tableContainer) {\n                tableContainer.scrollIntoView({ behavior: 'smooth', block: 'start' });\n            }\n        }\n\n        const kpiTotal = document.getElementById('kpi-card-total');\n        if(kpiTotal) kpiTotal.addEventListener('click', () => applyTableFilterAndScroll('risks-table', 'all', []));\n\n        const kpiSuper = document.getElementById('kpi-card-super');\n        if(kpiSuper) kpiSuper.addEventListener('click', () => applyTableFilterAndScroll('risks-table', 'class', ['Super cr\u00edtico', 'Supercr\u00edtico']));\n\n        const kpiCritico = document.getElementById('kpi-card-criticos');\n        if(kpiCritico) kpiCritico.addEventListener('click', () => applyTableFilterAndScroll('risks-table', 'class', ['Cr\u00edtico', 'Critico']));\n\n        const kpiMedio = document.getElementById('kpi-card-medios');\n        if(kpiMedio) kpiMedio.addEventListener('click', () => applyTableFilterAndScroll('risks-table', 'class', ['M\u00e9dio', 'Medio']));\n\n        // ---------------------------------------------------------\n        // Tema Claro / Escuro\n        // ---------------------------------------------------------\n        const settingsBtn = document.getElementById('settings-btn');\n        const settingsPanel = document.getElementById('settings-panel');\n        const closeSettingsBtn = document.getElementById('close-settings-btn');\n        const themeSelector = document.getElementById('theme-selector');\n\n        if (settingsBtn) {\n            settingsBtn.addEventListener('click', () => {\n                settingsPanel.classList.toggle('hidden');\n            });\n        }\n        if (closeSettingsBtn) {\n            closeSettingsBtn.addEventListener('click', () => {\n                settingsPanel.classList.add('hidden');\n            });\n        }\n        if (themeSelector) {\n            themeSelector.addEventListener('change', (e) => {\n                const theme = e.target.value;\n                if (theme === 'dark') {\n                    document.body.classList.add('dark-mode');\n                } else {\n                    document.body.classList.remove('dark-mode');\n                }\n                // Atualiza os gr\u00e1ficos para mudarem a cor da fonte e eixos\n                updateDashboard();\n            });\n        }\n\n        // ---------------------------------------------------------\n        // Editor Master (Drag & Drop Layout)\n        // ---------------------------------------------------------\n        const editorSelector = document.getElementById('editor-mode');\n        if (editorSelector) {\n            editorSelector.addEventListener('change', (e) => {\n                const isOn = e.target.value === 'on';\n                if (isOn) {\n                    document.body.classList.add('editor-mode-active');\n                    enableDragAndDrop();\n                } else {\n                    document.body.classList.remove('editor-mode-active');\n                    disableDragAndDrop();\n                }\n            });\n        }\n\n        let dragSrcEl = null;\n\n        function handleDragStart(e) {\n            dragSrcEl = this;\n            e.dataTransfer.effectAllowed = 'move';\n            e.dataTransfer.setData('text/plain', 'chart'); \n            this.style.opacity = '0.4';\n        }\n\n        function handleDragOver(e) {\n            if (e.preventDefault) e.preventDefault();\n            e.dataTransfer.dropEffect = 'move';\n            return false;\n        }\n\n        function handleDragEnter(e) {\n            this.classList.add('drag-over');\n        }\n\n        function handleDragLeave(e) {\n            this.classList.remove('drag-over');\n        }\n\n        function handleDrop(e) {\n            if (e.stopPropagation) e.stopPropagation();\n\n            if (dragSrcEl !== this) {\n                // Ao inv\u00e9s de trocar as caixas (o que quebrava o CSS Grid col-span-2),\n                // trocamos apenas o CONTE\u00daDO delas. As caixas de layout ficam fixas.\n                const tempNode = document.createElement('div');\n                \n                while (dragSrcEl.firstChild) {\n                    tempNode.appendChild(dragSrcEl.firstChild);\n                }\n                while (this.firstChild) {\n                    dragSrcEl.appendChild(this.firstChild);\n                }\n                while (tempNode.firstChild) {\n                    this.appendChild(tempNode.firstChild);\n                }\n                \n                // Dispara redimensionamento para os gr\u00e1ficos se ajustarem aos novos containers\n                setTimeout(() => { window.dispatchEvent(new Event('resize')); }, 50);\n            }\n            return false;\n        }\n\n        function handleDragEnd(e) {\n            this.style.opacity = '1';\n            const cards = document.querySelectorAll('.chart-card');\n            cards.forEach(c => c.classList.remove('drag-over'));\n        }\n\n        function enableDragAndDrop() {\n            const cards = document.querySelectorAll('.chart-card');\n            cards.forEach(card => {\n                card.setAttribute('draggable', 'true');\n                card.addEventListener('dragstart', handleDragStart, false);\n                card.addEventListener('dragenter', handleDragEnter, false);\n                card.addEventListener('dragover', handleDragOver, false);\n                card.addEventListener('dragleave', handleDragLeave, false);\n                card.addEventListener('drop', handleDrop, false);\n                card.addEventListener('dragend', handleDragEnd, false);\n            });\n        }\n\n        function disableDragAndDrop() {\n            const cards = document.querySelectorAll('.chart-card');\n            cards.forEach(card => {\n                card.setAttribute('draggable', 'false');\n                card.removeEventListener('dragstart', handleDragStart, false);\n                card.removeEventListener('dragenter', handleDragEnter, false);\n                card.removeEventListener('dragover', handleDragOver, false);\n                card.removeEventListener('dragleave', handleDragLeave, false);\n                card.removeEventListener('drop', handleDrop, false);\n                card.removeEventListener('dragend', handleDragEnd, false);\n            });\n        }\n\n    } catch (error) {\n        console.error(\"Erro ao inicializar o dashboard:\", error);\n    }\n});\n\nfunction getRiscosForWidget(widgetId) {\n    const riskSelect = document.querySelector(`.local-filter-select[data-filter-type=\"risk\"][data-target=\"${widgetId}\"]`);\n    const classSelect = document.querySelector(`.local-filter-select[data-filter-type=\"class\"][data-target=\"${widgetId}\"]`);\n    \n    const riskVal = riskSelect ? riskSelect.value : 'all';\n    const classVal = classSelect ? classSelect.value : 'all';\n    \n    // Regra 1: Tabelas IGNORAM filtro geral e modo comparativo\n    if (widgetId.includes('table')) {\n        let filtered = allRiscos;\n        if (riskVal !== 'all') filtered = filtered.filter(r => r.ID == riskVal);\n        if (classVal !== 'all') filtered = filtered.filter(r => r['Classifica\u00e7\u00e3o'] === classVal);\n        return { mode: 'normal', data: filtered };\n    }\n\n    // Regra 2: Gr\u00e1ficos reagem ao filtro geral e t\u00eam modo comparativo\n    const hasGlobal = currentGlobalFilter !== 'all';\n    const hasLocal = riskVal !== 'all' || classVal !== 'all';\n\n    if (!hasGlobal && !hasLocal) {\n        return { mode: 'normal', data: allRiscos };\n    }\n\n    let bucketA = [];\n    let labelA = '';\n    \n    if (hasLocal) {\n        bucketA = allRiscos.filter(r => {\n            let matchLocal = true;\n            if (riskVal !== 'all' && r.ID != riskVal) matchLocal = false;\n            if (classVal !== 'all' && r['Classifica\u00e7\u00e3o'] !== classVal) matchLocal = false;\n            return matchLocal;\n        });\n        \n        labelA = 'Filtro Local';\n        if (riskVal !== 'all') {\n            const rName = allRiscos.find(r => r.ID == riskVal);\n            if (rName) labelA = rName.Risco;\n        } else if (classVal !== 'all') {\n            labelA = `Classe: ${classVal}`;\n        }\n    } else if (hasGlobal) {\n        bucketA = allRiscos.filter(r => r.ID == currentGlobalFilter);\n        const rGlobal = allRiscos.find(r => r.ID == currentGlobalFilter);\n        labelA = rGlobal ? rGlobal.Risco : `Risco #${currentGlobalFilter}`;\n    }\n\n    let bucketB = [];\n    let labelB = '';\n\n    if (hasLocal && hasGlobal) {\n        bucketB = allRiscos.filter(r => r.ID == currentGlobalFilter && !bucketA.some(a => a.ID === r.ID));\n        const rGlobal = allRiscos.find(r => r.ID == currentGlobalFilter);\n        labelB = rGlobal ? rGlobal.Risco : `Risco #${currentGlobalFilter}`;\n    } else {\n        bucketB = allRiscos.filter(r => !bucketA.some(a => a.ID === r.ID));\n        labelB = 'Outros Riscos';\n    }\n\n    return { \n        mode: 'comparative', \n        bucketA: { data: bucketA, label: labelA },\n        bucketB: { data: bucketB, label: labelB }\n    };\n}\n\nfunction updateWidget(widgetId) {\n    const dataset = getRiscosForWidget(widgetId);\n    \n    if (widgetId === 'chart-cost') renderCostLineChart(dataset);\n    if (widgetId === 'chart-area') renderAreaChart(dataset);\n    if (widgetId === 'chart-category') renderCategoryChart(dataset);\n    if (widgetId === 'top-risks-table') populateTopRisksTable(dataset);\n    if (widgetId === 'risks-table') populateTable(dataset);\n}\n\nfunction updateKPICards() {\n    let baseData = allRiscos;\n    if (currentGlobalFilter !== 'all') {\n        baseData = allRiscos.filter(r => r.ID == currentGlobalFilter);\n    }\n\n    const total = baseData.reduce((sum, r) => sum + (r.Vulnerabilidades || 1), 0);\n    const superc = baseData.filter(r => r['Classifica\u00e7\u00e3o'].toLowerCase().includes('super'))\n                           .reduce((sum, r) => sum + (r.Vulnerabilidades || 1), 0);\n    const criticos = baseData.filter(r => r['Classifica\u00e7\u00e3o'].toLowerCase() === 'cr\u00edtico' || r['Classifica\u00e7\u00e3o'].toLowerCase() === 'critico')\n                             .reduce((sum, r) => sum + (r.Vulnerabilidades || 1), 0);\n    const medios = baseData.filter(r => r['Classifica\u00e7\u00e3o'].toLowerCase() === 'm\u00e9dio' || r['Classifica\u00e7\u00e3o'].toLowerCase() === 'medio' || r['Classifica\u00e7\u00e3o'].toLowerCase() === 'baixo')\n                           .reduce((sum, r) => sum + (r.Vulnerabilidades || 1), 0);\n\n    const elTotal = document.getElementById('kpi-total');\n    if (elTotal) elTotal.innerText = total;\n\n    const elSuper = document.getElementById('kpi-supercriticos');\n    if (elSuper) elSuper.innerText = superc;\n\n    const elCritico = document.getElementById('kpi-criticos');\n    if (elCritico) elCritico.innerText = criticos;\n\n    const elMedio = document.getElementById('kpi-medios');\n    if (elMedio) elMedio.innerText = medios;\n\n    const catCount = {};\n    baseData.forEach(r => { catCount[r.Categoria] = (catCount[r.Categoria] || 0) + (r.Vulnerabilidades || 1); });\n    let maxCat = '';\n    let maxVal = 0;\n    for (const [cat, count] of Object.entries(catCount)) {\n        if (count > maxVal) {\n            maxVal = count;\n            maxCat = cat;\n        }\n    }\n    const elMostFound = document.getElementById('kpi-most-found');\n    if (elMostFound) elMostFound.innerHTML = `<i class=\"ph ph-info\"></i> Risco mais encontrado: ${maxCat || 'Nenhum'}`;\n}\n\nfunction updateDashboard() {\n    updateKPICards();\n    updateWidget('chart-cost');\n    updateWidget('chart-area');\n    updateWidget('chart-category');\n    updateWidget('top-risks-table');\n    updateWidget('risks-table');\n}\n\n// Cores baseadas na paleta da Atl\u00e2ntica (CSS vars adaptadas para JS)\nconst colors = {\n    supercritico: '#E53E3E',\n    critico: '#DD6B20',\n    medio: '#D69E2E',\n    baixo: '#38A169',\n    primaryBlue: '#004A8F',\n    primaryGreen: '#00965E'\n};\n\nfunction getColorByClass(classificacao) {\n    if (!classificacao) return colors.primaryBlue;\n    const c = classificacao.toLowerCase();\n    if (c.includes('super')) return colors.supercritico;\n    if (c.includes('cr\u00edtico') || c.includes('critico')) return colors.critico;\n    if (c.includes('m\u00e9dio') || c.includes('medio')) return colors.medio;\n    return colors.baixo;\n}\n\nfunction getVulnColor(vuln) {\n    if (!vuln || vuln <= 1) return colors.baixo; // Green\n    if (vuln <= 3) return colors.medio; // Yellow\n    return colors.supercritico; // Red\n}\n\nfunction formatCurrency(val) {\n    if (val >= 1000000) return 'R$ ' + (val/1000000).toFixed(2) + 'M';\n    if (val >= 1000) return 'R$ ' + (val/1000).toFixed(2) + 'K';\n    return 'R$ ' + val.toFixed(2);\n}\n\nfunction renderCostLineChart(dataset) {\n    const isDark = document.body.classList.contains('dark-mode');\n    const textColor = isDark ? '#F1F5F9' : '#1A202C';\n    const gridColor = isDark ? '#334155' : '#E2E8F0';\n\n    let trace1;\n    let layout = {\n        margin: { t: 40, r: 40, b: 80, l: 100 },\n        font: { color: textColor },\n        plot_bgcolor: 'transparent',\n        paper_bgcolor: 'transparent',\n        hovermode: 'closest'\n    };\n\n    if (dataset.mode === 'comparative') {\n        const avgA = dataset.bucketA.data.length ? dataset.bucketA.data.reduce((s, r) => s + r['Gasto M\u00e9dio Num\u00e9rico'], 0) / dataset.bucketA.data.length : 0;\n        const avgB = dataset.bucketB.data.length ? dataset.bucketB.data.reduce((s, r) => s + r['Gasto M\u00e9dio Num\u00e9rico'], 0) / dataset.bucketB.data.length : 0;\n\n        const vulnA = dataset.bucketA.data.reduce((s, r) => s + (r.Vulnerabilidades || 1), 0);\n        const vulnB = dataset.bucketB.data.reduce((s, r) => s + (r.Vulnerabilidades || 1), 0);\n\n        trace1 = {\n            x: [vulnA, vulnB],\n            y: [avgA, avgB],\n            mode: 'markers+text',\n            type: 'scatter',\n            marker: { size: 25, color: [colors.supercritico, colors.primaryBlue], opacity: 0.8 },\n            text: [dataset.bucketA.label, dataset.bucketB.label],\n            textposition: 'top center',\n            hovertext: [\n                `<b>${dataset.bucketA.label}</b><br>Vulnerabilidades: ${vulnA}<br>M\u00e9dia: ${formatCurrency(avgA)}`,\n                `<b>${dataset.bucketB.label}</b><br>Vulnerabilidades: ${vulnB}<br>M\u00e9dia: ${formatCurrency(avgB)}`\n            ],\n            hoverinfo: 'text'\n        };\n        layout.xaxis = { automargin: true, title: 'Quantidade de Vulnerabilidades', gridcolor: gridColor, fixedrange: true, rangemode: 'tozero' };\n        layout.yaxis = { automargin: true, title: 'Gasto M\u00e9dio Estimado', tickprefix: 'R$ ', gridcolor: gridColor, fixedrange: true, rangemode: 'tozero' };\n    } else {\n        const riscos = dataset.data;\n        const sorted = [...riscos].sort((a, b) => b['Gasto M\u00e9dio Num\u00e9rico'] - a['Gasto M\u00e9dio Num\u00e9rico']).slice(0, 5);\n        \n        const grouped = {};\n        sorted.forEach(r => {\n            const vuln = r.Vulnerabilidades || 1;\n            const gasto = r['Gasto M\u00e9dio Num\u00e9rico'];\n            const key = `${vuln}_${gasto}`;\n            if (!grouped[key]) {\n                grouped[key] = { x: vuln, y: gasto, riscos: [] };\n            }\n            grouped[key].riscos.push(r);\n        });\n        const plotData = Object.values(grouped);\n\n        trace1 = {\n            x: plotData.map(g => g.x),\n            y: plotData.map(g => g.y),\n            mode: 'markers+text',\n            type: 'scatter',\n            marker: { \n                size: plotData.map(g => g.riscos.length > 1 ? 28 : 20), \n                color: colors.primaryBlue, \n                opacity: 0.8 \n            },\n            text: plotData.map(g => g.riscos.length > 1 ? `${g.riscos.length} Riscos agrupados` : `Risco #${g.riscos[0].ID}`),\n            textposition: 'top center',\n            hovertext: plotData.map(g => {\n                return g.riscos.map(r => `<b>${r.Risco}</b><br>ID #${r.ID} | Vuln: ${r.Vulnerabilidades || 1} | Custo: ${r['Custo Estimado']}`).join('<br>\u2501<br>');\n            }),\n            hoverinfo: 'text'\n        };\n        layout.xaxis = { automargin: true, title: 'Quantidade de Vulnerabilidades', gridcolor: gridColor, fixedrange: true, rangemode: 'tozero' };\n        layout.yaxis = { automargin: true, title: 'Gasto M\u00e9dio Estimado', tickprefix: 'R$ ', gridcolor: gridColor, fixedrange: true, rangemode: 'tozero' };\n    }\n\n    const config = { responsive: true, displayModeBar: false };\n    Plotly.react('chart-cost', [trace1], layout, config);\n}\n\nfunction renderAreaChart(dataset) {\n    const isDark = document.body.classList.contains('dark-mode');\n    const textColor = isDark ? '#F1F5F9' : '#1A202C';\n    const gridColor = isDark ? '#334155' : '#E2E8F0';\n\n    let trace;\n    let layout = {\n        margin: { t: 40, r: 40, b: 140, l: 80 },\n        font: { color: textColor },\n        plot_bgcolor: 'transparent',\n        paper_bgcolor: 'transparent',\n    };\n\n    if (dataset.mode === 'comparative') {\n        const countA = dataset.bucketA.data.reduce((sum, r) => sum + (r.Vulnerabilidades || 1), 0);\n        const countB = dataset.bucketB.data.reduce((sum, r) => sum + (r.Vulnerabilidades || 1), 0);\n        trace = {\n            x: [dataset.bucketA.label, dataset.bucketB.label],\n            y: [countA, countB],\n            type: 'bar',\n            marker: { color: [colors.supercritico, colors.primaryBlue] },\n            text: [countA, countB],\n            textposition: 'auto'\n        };\n        layout.xaxis = { automargin: true, tickangle: -45, fixedrange: true, type: 'category' };\n        layout.yaxis = { automargin: true, title: 'Quantidade de Vulnerabilidades', gridcolor: gridColor, fixedrange: true };\n    } else {\n        const riscos = dataset.data;\n        const areaCount = {};\n        riscos.forEach(r => { areaCount[r.\u00c1rea] = (areaCount[r.\u00c1rea] || 0) + (r.Vulnerabilidades || 1); });\n        const xData = Object.keys(areaCount);\n        \n        trace = {\n            x: xData,\n            y: Object.values(areaCount),\n            type: 'bar',\n            marker: { color: colors.primaryBlue, opacity: 0.9 }\n        };\n        const padding = xData.length === 1 ? 1.5 : (xData.length === 2 ? 0.8 : 0.5);\n        layout.xaxis = { automargin: true, tickangle: -45, fixedrange: true, range: [-padding, xData.length - 1 + padding] };\n        layout.yaxis = { automargin: true, title: 'Quantidade de Vulnerabilidades', gridcolor: gridColor, fixedrange: true };\n    }\n\n    const config = { responsive: true, displayModeBar: false };\n    Plotly.react('chart-area', [trace], layout, config);\n}\n\nfunction renderCategoryChart(dataset) {\n    const isDark = document.body.classList.contains('dark-mode');\n    const textColor = isDark ? '#F1F5F9' : '#1A202C';\n\n    let trace;\n    if (dataset.mode === 'comparative') {\n        const countA = dataset.bucketA.data.reduce((sum, r) => sum + (r.Vulnerabilidades || 1), 0);\n        const countB = dataset.bucketB.data.reduce((sum, r) => sum + (r.Vulnerabilidades || 1), 0);\n        trace = {\n            labels: [dataset.bucketA.label, dataset.bucketB.label],\n            values: [countA, countB],\n            type: 'pie',\n            marker: { colors: [colors.supercritico, colors.primaryBlue] },\n            textinfo: 'percent+label',\n            textposition: 'auto',\n            hoverinfo: 'label+value'\n        };\n    } else {\n        const riscos = dataset.data;\n        const catCount = {};\n        riscos.forEach(r => { catCount[r.Categoria] = (catCount[r.Categoria] || 0) + (r.Vulnerabilidades || 1); });\n        trace = {\n            labels: Object.keys(catCount),\n            values: Object.values(catCount),\n            type: 'pie',\n            marker: { colors: [colors.primaryBlue, colors.primaryGreen, '#0066CC', '#00B371', '#38A169', '#E6F0FA'] },\n            textinfo: 'percent',\n            textposition: 'auto',\n            hoverinfo: 'label+value'\n        };\n    }\n\n    const layout = {\n        margin: { t: 40, r: 40, b: 120, l: 40 },\n        font: { color: textColor },\n        showlegend: true,\n        legend: { orientation: 'h', y: -0.3, itemclick: false, itemdoubleclick: false },\n        paper_bgcolor: 'transparent',\n    };\n\n    const config = { responsive: true, displayModeBar: false };\n    Plotly.react('chart-category', [trace], layout, config);\n}\n\nfunction populateTopRisksTable(dataset) {\n    const tableBody = document.querySelector('#top-risks-table tbody');\n    tableBody.innerHTML = '';\n    \n    const riscos = dataset.data || [];\n    const sorted = [...riscos].sort((a, b) => b['Custo Mensal Num\u00e9rico'] - a['Custo Mensal Num\u00e9rico']).slice(0, 5);\n\n    sorted.forEach((risco, index) => {\n        const tr = document.createElement('tr');\n        const color = getColorByClass(risco.Classifica\u00e7\u00e3o);\n        const vulnVal = risco.Vulnerabilidades || 1;\n        const vulnColor = getVulnColor(vulnVal);\n        \n        tr.innerHTML = `\n            <td>${risco.ID}</td>\n            <td>${risco.Risco}</td>\n            <td>${risco.Categoria}</td>\n            <td><span class=\"status-badge\" style=\"background-color: ${color}20; color: ${color}; padding: 4px 8px; border-radius: 12px; font-weight: 600;\">${risco.Classifica\u00e7\u00e3o}</span></td>\n            <td style=\"font-weight: 600;\">${risco['Custo Mensal']}</td>\n            <td><span style=\"background-color: ${vulnColor}20; border: 1px solid ${vulnColor}; color: ${vulnColor}; font-weight: bold; padding: 4px 12px; border-radius: 8px;\">${vulnVal}</span></td>\n        `;\n        tableBody.appendChild(tr);\n    });\n}\n\nfunction populateTable(dataset) {\n    const tableBody = document.querySelector('#risks-table tbody');\n    if (!tableBody) return;\n    tableBody.innerHTML = '';\n    \n    const riscos = dataset.data || [];\n    const sorted = [...riscos].sort((a, b) => a.ID - b.ID);\n\n    sorted.forEach(risco => {\n        const tr = document.createElement('tr');\n        const color = getColorByClass(risco.Classifica\u00e7\u00e3o);\n        const vulnVal = risco.Vulnerabilidades || 1;\n        const vulnColor = getVulnColor(vulnVal);\n\n        tr.innerHTML = `\n            <td>${risco.ID || ''}</td>\n            <td>${risco.Risco || ''}</td>\n            <td>${risco.\u00c1rea || ''}</td>\n            <td><span class=\"status-badge\" style=\"background-color: ${color}20; color: ${color}; padding: 4px 8px; border-radius: 12px; font-weight: 600;\">${risco.Classifica\u00e7\u00e3o || ''}</span></td>\n            <td>${risco['Custo Mensal'] || ''}</td>\n            <td>${risco['Custo Estimado'] || ''}</td>\n            <td><span style=\"background-color: ${vulnColor}20; border: 1px solid ${vulnColor}; color: ${vulnColor}; font-weight: bold; padding: 4px 12px; border-radius: 8px;\">${vulnVal}</span></td>\n        `;\n        tableBody.appendChild(tr);\n    });\n}\n\n// Export Button Listener\ndocument.addEventListener('DOMContentLoaded', () => {\n    const exportBtn = document.getElementById('export-btn');\n    if (exportBtn) {\n        exportBtn.addEventListener('click', () => {\n            // Pequeno delay para garantir que qualquer anima\u00e7\u00e3o CSS finalize e o layout fique pronto\n            setTimeout(() => window.print(), 200);\n        });\n    }\n});\n";
